import random

def solve_optimal(s):
    depth = 0
    best = 0
    for ch in s:
        if ch == "(":
            depth += 1
            best = max(best, depth)
        else:
            depth -= 1
            if depth < 0:
                return -1
    return best if depth == 0 else -1

def solve_brute(s):
    rounds = 0
    while s:
        reduced = s.replace("()", "")
        if reduced == s:
            return -1
        s = reduced
        rounds += 1
    return rounds

def gen(rng, size):
    low, high = {"tiny": (0, 4), "small": (0, 10), "large": (20, 60)}[size]
    n = rng.randint(low, high)
    if rng.random() < 0.5:
        out, open_count = [], 0
        for _ in range(n):
            if open_count > 0 and rng.random() < 0.5:
                out.append(")")
                open_count -= 1
            else:
                out.append("(")
                open_count += 1
        out.extend(")" * open_count)
        return ["".join(out)]
    return ["".join(rng.choice("()") for _ in range(n))]

def validate(args):
    return isinstance(args[0], str) and len(args[0]) <= 10**5 and set(args[0]) <= set("()")
